function WorkspaceSidebar({ active = "/dashboard", onClose }: { active?: string; onClose?: () => void }) {
  const { t } = useLocale();
  const [location] = useLocation();
  const [modeOpen, setModeOpen] = useState(false);
  const [mode, setMode] = useState<"founder" | "learner">(() => {
    if (typeof window === "undefined") return "founder";
    return window.localStorage.getItem("asaasi-view-mode") === "learner" ? "learner" : "founder";
  });
  useEffect(() => {
    if (location.startsWith("/dashboard/learner")) setMode("learner");
    else if (location === "/dashboard") setMode("founder");
  }, [location]);
  useEffect(() => { window.localStorage.setItem("asaasi-view-mode", mode); }, [mode]);
  return <aside className="workspace-sidebar">
    <div className="workspace-profile"><div className="avatar avatar-yellow">SA</div><div><strong>Sara Ammar</strong><span>{t("Founder · Cairo", "مؤسسة · القاهرة")}</span></div><button type="button" className="icon-button mobile-only" onClick={onClose} aria-label={t("Close workspace menu", "إغلاق قائمة مساحة العمل")}><X size={16} /></button></div>
    <div className="mode-switcher"><span className="mono">{t("Active view", "العرض النشط")}</span><button type="button" className="mode-switcher-current" aria-expanded={modeOpen} aria-haspopup="true" onClick={() => setModeOpen((value) => !value)}>{mode === "learner" ? <BookOpen size={15} /> : <BriefcaseBusiness size={15} />} {mode === "learner" ? t("Learner view", "عرض المتعلم") : t("Founder workspace", "مساحة المؤسس")} <ChevronRight size={14} style={{ transform: modeOpen ? "rotate(90deg)" : undefined, transition: "transform 160ms" }} /></button>{modeOpen && <div className="mode-switcher-menu" role="menu"><Link href="/dashboard" role="menuitem" className={mode === "founder" ? "mode-switcher-option is-active" : "mode-switcher-option"} onClick={() => { setModeOpen(false); onClose?.(); }}><BriefcaseBusiness size={14} /> {t("Founder workspace", "مساحة المؤسس")} {mode === "founder" && <Check size={14} />}</Link><Link href="/dashboard/learner" role="menuitem" className={mode === "learner" ? "mode-switcher-option is-active" : "mode-switcher-option"} onClick={() => { setModeOpen(false); onClose?.(); }}><BookOpen size={14} /> {t("Learner view", "عرض المتعلم")} {mode === "learner" && <Check size={14} />}</Link></div>}<p>{t("Switch modes without losing your place.", "بدل المساحات دون أن تفقد مكانك.")}</p></div>
    <nav className="workspace-nav" aria-label={t("Workspace navigation", "تنقل مساحة العمل")}>{(mode === "learner" ? learnerLinks : dashboardLinks).map(([href, label, Icon]) => { const isActive = location === href || (href !== "/dashboard" && location.startsWith(href)); const labels: Record<string, string> = { Home: t("Home", "الرئيسية"), "Learning path": t("Learning path", "مسار التعلم"), "AI coach": t("AI coach", "مساعد الذكاء الاصطناعي"), "Find people": t("Find people", "ابحث عن أشخاص"), Network: t("Network", "شبكتك"), Community: t("Community", "المجتمع"), Professionals: t("Professionals", "المتخصصون"), Events: t("Events", "الفعاليات"), "My events": t("My events", "فعالياتي"), Requests: t("Requests", "الطلبات"), Invitations: t("Invitations", "الدعوات"), Membership: t("Membership", "العضوية"), "Membership perks": t("Membership perks", "مزايا العضوية"), Saved: t("Saved", "المحفوظات"), Following: t("Following", "المتابَعون"), Registrations: t("Registrations", "التسجيلات"), Organizations: t("Organizations", "المنظمات"), "My profile": t("My profile", "ملفي الشخصي"), Settings: t("Settings", "الإعدادات") }; return <Link key={href} href={href} onClick={onClose} className={isActive ? "active" : ""} aria-current={isActive ? "page" : undefined}><Icon size={16} /><span>{labels[label] ?? label}</span>{label === "Saved" && <small aria-label={t("3 saved items", "٣ عناصر محفوظة")}>3</small>}</Link>; })}</nav>
    <div className="sidebar-brief"><SectionLabel>{t("Next signal", "الإشارة التالية")}</SectionLabel><strong>{t("Review your pricing brief", "راجع ملخص التسعير")}</strong><p>{t("12 min · based on your founder stage.", "١٢ دقيقة · وفق مرحلة مؤسستك.")}</p><Link href="/tools/pricing-advisor">{t("Open tool", "فتح الأداة")} <ArrowRight size={13} /></Link></div>
  </aside>;
}

export function ProductShell({ children, title, active }: { children: ReactNode; title?: string; active?: string }) {
  const { t } = useLocale();
  const { isAuthed } = useAuth();
  const [menu, setMenu] = useState(false);
  const [location, setLocation] = useLocation();
  useEffect(() => {
    const isAuthRoute = location === "/login" || location === "/signup" || location === "/forgot-password" || location === "/reset-password" || location === "/verify-email";
    if (!isAuthed && !isAuthRoute) {
      window.sessionStorage.setItem("asaasi-return-route", location);
      setLocation("/login");
    }
  }, [isAuthed, location, setLocation]);
  useEffect(() => { if (title) document.title = `${title} · ASaaSI`; return () => { document.title = "ASaaSI · MENA SaaS Founder Community"; }; }, [title]);
  if (!isAuthed) return <main className="empty-state" style={{ margin: "80px auto", maxWidth: 420 }} aria-busy="true" aria-live="polite"><LockKeyhole size={20} aria-hidden="true" /><h2>{t("Sign in required.", "تسجيل الدخول مطلوب.")}</h2><p role="status">{t("Taking you to login...", "جار نقلك إلى تسجيل الدخول...")}</p></main>;
  return <div className="product-shell"><div className="product-mobile-menu"><button type="button" className="button button-ghost" aria-expanded={menu} aria-controls="workspace-sidebar" onClick={() => setMenu(!menu)}><Menu size={16} /> {menu ? t("Close workspace", "إغلاق مساحة العمل") : t("Open workspace", "فتح مساحة العمل")}</button></div><div className="product-shell-grid">{menu && <button type="button" className="product-sidebar-overlay" aria-label={t("Close workspace navigation", "إغلاق تنقل مساحة العمل")} onClick={() => setMenu(false)} />}<div id="workspace-sidebar" className={menu ? "workspace-sidebar-wrap open" : "workspace-sidebar-wrap"}><WorkspaceSidebar active={active} onClose={() => setMenu(false)} /></div><main id="main-content" data-workspace-route={active} className="product-main">{children}</main></div></div>;
}

function FounderBriefChecklist() {
  const { t, formatNum } = useLocale();
  const [complete, setComplete] = useState<boolean[]>(() => {
    if (typeof window === "undefined") return [true, false, false];
    const saved = window.localStorage.getItem("asaasi-founder-brief");
    return saved ? JSON.parse(saved) : [true, false, false];
  });
  useEffect(() => { window.localStorage.setItem("asaasi-founder-brief", JSON.stringify(complete)); }, [complete]);
  const steps = [
    { label: t("Define your signal", "حدد إشارتك"), detail: t("Profile and founder context", "الملف الشخصي وسياق المؤسس"), href: "/dashboard/profile" },
    { label: t("Choose one move", "اختر خطوة واحدة"), detail: t("People, requests, or an event", "أشخاص أو طلبات أو فعالية"), href: "/matching" },
    { label: t("Make the next move", "اتخذ الخطوة التالية"), detail: t("Create a focused request", "أنشئ طلبا مركزا"), href: "/requests/new" },
  ];
  const completed = complete.filter(Boolean).length;
  return <section className="founder-brief-persisted" aria-labelledby="founder-brief-persisted-title"><div className="founder-brief-copy"><span className="mono">{t("Persistent founder brief", "ملخص المؤسس المستمر")}</span><h2 id="founder-brief-persisted-title">{t("Keep the next move visible.", "أبقِ الخطوة التالية واضحة.")}</h2><p>{t(`${completed} of 3 signals are complete. This checklist follows your account, not a single session.`, `اكتملت ${formatNum(completed)} من ٣ إشارات. تتبع هذه القائمة حسابك، لا جلسة واحدة.`)}</p></div><ol>{steps.map((step, index) => <li key={step.href} className={complete[index] ? "is-complete" : ""}><button type="button" className="brief-check" aria-pressed={complete[index]} aria-label={t(`Mark ${step.label} complete`, `وضع ${step.label} كمكتمل`)} onClick={() => setComplete((current) => current.map((value, itemIndex) => itemIndex === index ? !value : value))}>{complete[index] ? <Check size={14} /> : <span>{String(index + 1).padStart(2, "0")}</span>}</button><div><strong>{step.label}</strong><small>{step.detail}</small></div><Link href={step.href} className="text-link">{t("Open", "فتح")} <ArrowRight size={13} /></Link></li>)}</ol></section>;
}

