function FounderOperatingDesk() {
  const { t, formatNum, isRTL } = useLocale();
  const [priority, setPriority] = useState(() => typeof window === "undefined" ? "pricing" : window.localStorage.getItem("asaasi-desk-priority") || "pricing");
  const [savedPricing, setSavedPricing] = useState(() => typeof window !== "undefined" && window.localStorage.getItem("asaasi-desk-saved-pricing") === "true");
  useEffect(() => { window.localStorage.setItem("asaasi-desk-priority", priority); }, [priority]);
  useEffect(() => { window.localStorage.setItem("asaasi-desk-saved-pricing", String(savedPricing)); }, [savedPricing]);
  const priorities = [
    { id: "pricing", label: t("Pricing", "التسعير"), title: t("Give the next offer a clearer shape.", "امنح العرض التالي شكلا أوضح."), copy: t("Keep the buyer, value proof, and one price hypothesis in a single decision record.", "أبقِ المشتري ودليل القيمة وفرضية سعر واحدة في سجل قرار واحد."), href: "/tools/pricing", action: t("Open pricing decision", "افتح قرار التسعير") },
    { id: "customers", label: t("Customers", "العملاء"), title: t("Turn one customer signal into evidence.", "حوّل إشارة عميل واحدة إلى دليل."), copy: t("Capture the customer language that should change your next experiment.", "التقط لغة العميل التي ينبغي أن تغيّر تجربتك التالية."), href: "/tools/customer-evidence", action: t("Open customer evidence", "افتح دليل العميل") },
    { id: "growth", label: t("Growth", "النمو"), title: t("Choose one channel worth another week.", "اختر قناة تستحق أسبوعا آخر."), copy: t("Frame the audience, channel, and proof that earn the next test.", "صغ الجمهور والقناة والدليل الذي يستحق الاختبار التالي."), href: "/tools/gtm-map", action: t("Open channel map", "افتح خريطة القنوات") }
  ];
  const current = priorities.find((item) => item.id === priority) ?? priorities[0];
  const upcoming = events[0];
  return <ProductShell active="/dashboard"><div className="founder-operating-desk">
    <header className="founder-desk-intro"><div><SectionLabel>{t("Founder operating desk", "مكتب تشغيل المؤسس")}</SectionLabel><h1>{t("Make one useful move today.", "اتخذ خطوة مفيدة واحدة اليوم.")}</h1><p>{t("Your desk keeps the decision, work, and next conversation together so you can return without rebuilding the context.", "يجمع مكتبك القرار والعمل والمحادثة التالية حتى تعود دون إعادة بناء السياق.")}</p></div><Link href="/dashboard/profile" className="text-link">{t("Edit founder context", "عدل سياق المؤسس")} {isRTL ? <ArrowLeft size={14} /> : <ArrowRight size={14} />}</Link></header>
    <section className="founder-desk-priority" aria-labelledby="founder-desk-priority-title"><div className="founder-desk-priority__copy"><span className="mono">{t("CURRENT PRIORITY", "الأولوية الحالية")}</span><h2 id="founder-desk-priority-title">{current.title}</h2><p>{current.copy}</p><Link href={current.href} className="button button-primary">{current.action} {isRTL ? <ArrowLeft size={15} /> : <ArrowRight size={15} />}</Link></div><div className="founder-desk-priority__selector" role="group" aria-label={t("Choose current priority", "اختر الأولوية الحالية")}><span className="mono">{t("Work on", "اعمل على")}</span>{priorities.map((item) => <button key={item.id} type="button" className={priority === item.id ? "is-active" : ""} aria-pressed={priority === item.id} onClick={() => setPriority(item.id)}>{item.label}</button>)}</div></section>
    <section className="founder-desk-records" aria-label={t("Your current operating records", "سجلاتك التشغيلية الحالية")}><article><span className="mono">{t("SAVED WORK", "العمل المحفوظ")}</span><h2>{savedPricing ? t("Pricing decision saved", "تم حفظ قرار التسعير") : t("No pricing decision saved yet", "لم يتم حفظ قرار تسعير بعد")}</h2><p>{savedPricing ? t("Return to the buyer, value proof, and price hypothesis when the next conversation changes the evidence.", "عد إلى المشتري ودليل القيمة وفرضية السعر عندما تغيّر المحادثة التالية الدليل.") : t("Save one concise decision record before you ask for feedback or change the offer.", "احفظ سجل قرار موجزا قبل أن تطلب ملاحظات أو تغيّر العرض.")}</p><div><button type="button" className="button button-light" onClick={() => setSavedPricing((value) => !value)}>{savedPricing ? t("Remove saved decision", "أزل القرار المحفوظ") : t("Save pricing decision", "احفظ قرار التسعير")}</button><Link href="/dashboard/saved" className="text-link">{t("View saved work", "اعرض العمل المحفوظ")} {isRTL ? <ArrowLeft size={13} /> : <ArrowRight size={13} />}</Link></div></article><article><span className="mono">{t("APPLICATIONS", "الطلبات")}</span><h2>{t("No active application", "لا يوجد طلب نشط")}</h2><p>{t("Bring one partner, provider, or event brief when you are ready to create a useful handoff.", "أحضر موجزا واحدا لشريك أو مزود أو فعالية عندما تكون مستعدا لإنشاء انتقال مفيد.")}</p><div><Link href="/partners/apply" className="button button-light">{t("Apply as a partner", "تقدم كشريك")} {isRTL ? <ArrowLeft size={13} /> : <ArrowRight size={13} />}</Link><Link href="/dashboard/registrations" className="text-link">{t("View activity", "اعرض النشاط")} {isRTL ? <ArrowLeft size={13} /> : <ArrowRight size={13} />}</Link></div></article><article><span className="mono">{t("UPCOMING EVENT", "الفعالية القادمة")}</span><h2>{t(upcoming.title, upcoming.arTitle)}</h2><p>{formatNum(upcoming.day)} {t(upcoming.month, monthAr[upcoming.month])} · {t(upcoming.location, upcoming.arLocation)} · {t(upcoming.outcome, upcoming.arOutcome)}</p><div><Link href={upcoming.href} className="button button-light">{t("View event", "شاهد الفعالية")} {isRTL ? <ArrowLeft size={13} /> : <ArrowRight size={13} />}</Link><Link href="/events" className="text-link">{t("Browse events", "تصفح الفعاليات")} {isRTL ? <ArrowLeft size={13} /> : <ArrowRight size={13} />}</Link></div></article></section>
    <section className="founder-desk-next" aria-labelledby="founder-desk-next-title"><div><SectionLabel>{t("Recommended next action", "الخطوة التالية الموصى بها")}</SectionLabel><h2 id="founder-desk-next-title">{t("Write the question before asking the network.", "اكتب السؤال قبل أن تسأل الشبكة.")}</h2><p>{t("A useful request names the decision, the constraint, and the input you need. Start with the question that would change your next move.", "يسمي الطلب المفيد القرار والقيد والمدخل الذي تحتاجه. ابدأ بالسؤال الذي سيغير خطوتك التالية.")}</p></div><div className="founder-desk-next__actions"><Link href="/requests/new" className="button button-dark">{t("Create focused request", "أنشئ طلبا مركزا")} {isRTL ? <ArrowLeft size={15} /> : <ArrowRight size={15} />}</Link><Link href="/matching" className="text-link">{t("Find relevant people", "ابحث عن أشخاص مناسبين")} {isRTL ? <ArrowLeft size={13} /> : <ArrowRight size={13} />}</Link></div></section>
  </div></ProductShell>;
}

