function LearnerWorkspace() {
  const { t } = useLocale();
  const [done, setDone] = useState(false);
  const [notesViewed, setNotesViewed] = useState(false);
  const [subscriber] = useState(() => typeof window !== "undefined" && window.localStorage.getItem("asaasi-access-tier") === "subscriber");
  return <ProductShell title={t("Learning path", "مسار التعلم")} active="/dashboard/learner"><div className="product-page-heading"><div><SectionLabel>{t("Learning path / Stage 02", "مسار التعلم / المرحلة ٠٢")}</SectionLabel><h1>{t("Build the habit before you build the funnel.", "ابنِ العادة قبل أن تبني القمع.")}</h1><p>{t("Free members can build the fundamentals. Member tracks add the deeper operating sequence when the basics are in motion.", "يمكن للأعضاء المجانيين بناء الأساسيات. وتضيف مسارات العضوية التسلسل التشغيلي الأعمق عندما تتحرك الأساسيات.")}</p></div><div className="heading-stat"><span className="mono">{t("Progress", "التقدم")}</span><strong>{done ? "3 / 4" : "2 / 4"}</strong><div className="mini-progress"><span style={{ width: done ? "75%" : "50%" }} /></div></div></div><div className="learning-path"><div className="learning-path-rail"><span className="path-dot active" /><span className="path-stem" /><span className="path-dot active" /><span className="path-stem" /><span className={`path-dot ${done ? "active" : ""}`} /><span className="path-stem" /><span className={`path-dot ${subscriber ? "active" : ""}`} /></div><div className="learning-steps"><article className="learning-step complete"><span className="mono">01 / {t("complete", "مكتمل")}</span><h2>{t("Find the signal", "اعثر على الإشارة")}</h2><p>{t("Turn a broad audience into a specific customer problem.", "حول جمهورا واسعا إلى مشكلة عميل محددة.")}</p><button type="button" className="text-link" onClick={() => setDone(false)}>{t("Review step", "راجع الخطوة")} <ArrowRight size={14} /></button></article><article className="learning-step complete"><span className="mono">02 / {t("complete", "مكتمل")}</span><h2>{t("Test the promise", "اختبر الوعد")}</h2><p>{t("Write a promise that can survive five real conversations.", "اكتب وعدا يصمد أمام خمس محادثات حقيقية.")}</p><button type="button" className="text-link" onClick={() => setNotesViewed((viewed) => !viewed)}>{notesViewed ? t("Notes reviewed", "تمت مراجعة الملاحظات") : t("View notes", "عرض الملاحظات")} <ArrowRight size={14} /></button>{notesViewed && <span className="action-feedback" role="status"><Check size={13} /> {t("Notes marked as reviewed", "تم وضع الملاحظات كمراجعة")}</span>}</article><article className={`learning-step ${done ? "complete" : "current"}`}><span className="mono">03 / {t("next", "التالي")}</span><h2>{t("Choose one channel", "اختر قناة واحدة")}</h2><p>{t("Make one distribution bet and define the evidence you need.", "راهن على قناة توزيع واحدة وحدد الدليل الذي تحتاجه.")}</p><button type="button" className="button button-primary" onClick={() => setDone(true)}>{done ? t("Completed", "مكتمل") : t("Start module", "ابدأ الوحدة")} <ArrowRight size={14} /></button></article><article className={`learning-step ${subscriber ? "current" : "locked"}`}><span className="mono">04 / {subscriber ? t("available", "متاح") : t("member track", "مسار العضوية")}</span><h2>{t("Make growth repeatable", "اجعل النمو قابلا للتكرار")}</h2><p>{subscriber ? t("Turn your evidence into a weekly operating rhythm and save the decisions that matter.", "حول دليلك إلى إيقاع تشغيلي أسبوعي واحفظ القرارات المهمة.") : t("Full learning tracks are part of Member access. Your completed fundamentals stay available.", "مسارات التعلم الكاملة جزء من وصول العضوية. ستظل أساسياتك المكتملة متاحة.")}</p>{subscriber ? <button type="button" className="button button-primary" onClick={() => setDone(true)}>{t("Open member track", "افتح مسار العضوية")} <ArrowRight size={14} /></button> : <Link href="/dashboard/billing" className="button button-light"><LockKeyhole size={14} /> {t("See Member access", "شاهد وصول العضوية")}</Link>}</article></div></div><div className="coach-callout"><Sparkles size={20} /><div><span className="mono">{t("Coach prompt · Free Member", "محفز المساعد · عضو مجاني")}</span><strong>“{t("What would you need to see to keep this channel for another 30 days?", "ما الذي تحتاج إلى رؤيته للإبقاء على هذه القناة ٣٠ يوما أخرى؟")}”</strong></div><Link href="/dashboard/coach" className="button button-dark">{t("Ask coach", "اسأل المساعد")} <ArrowRight size={14} /></Link></div></ProductShell>;
}

function CoachWorkspace() {
  const { t } = useLocale();
  const [prompt, setPrompt] = useState("");
  const [sent, setSent] = useState(false);
  return <ProductShell title={t("AI coach", "مساعد الذكاء الاصطناعي")} active="/dashboard/coach"><div className="coach-layout"><div className="product-page-heading"><SectionLabel>{t("Coach / Practical mirror", "المساعد / مرآة عملية")}</SectionLabel><h1>{t("Bring one decision. Leave with a smaller next step.", "أحضر قرارا واحدا، وغادر بخطوة تالية أصغر.")}</h1><p>{t("The coach is not a chatbot wall. It keeps the context of your stage, learning path, and saved work.", "المساعد ليس جدار محادثة. بل يحتفظ بسياق مرحلتك ومسار تعلمك وعملك المحفوظ.")}</p></div><div className="coach-thread"><div className="coach-message coach-system"><span className="coach-orb"><Sparkles size={15} /></span><div><span className="mono">{t("ASaaSI coach · just now", "مساعد أساسي · الآن")}</span><p>{t("You are exploring pricing and early repeatability. What decision is currently taking up the most space?", "أنت تستكشف التسعير وقابلية التكرار المبكرة. ما القرار الذي يشغل أكبر مساحة الآن؟")}</p></div></div>{sent && <div className="coach-message coach-user"><span className="mono">{t("You", "أنت")}</span><p>{prompt}</p></div>}{sent && <div className="coach-message coach-system"><span className="coach-orb"><Sparkles size={15} /></span><div><span className="mono">{t("A smaller frame", "إطار أصغر")}</span><p>{t("Ask three customers what they thought they were paying for before you decide what to rename. Then bring the language back here.", "اسأل ثلاثة عملاء عما ظنوا أنهم يدفعون مقابله قبل أن تقرر ما الذي ستعيد تسميته. ثم أحضر اللغة إلى هنا.")}</p><Link href="/requests/new" className="text-link">{t("Turn this into an ask", "حول هذا إلى طلب")} <ArrowRight size={14} /></Link></div></div>}</div><form className="coach-composer" onSubmit={(event) => { event.preventDefault(); if (prompt.trim()) setSent(true); }}><textarea value={prompt} onChange={(event) => setPrompt(event.target.value)} placeholder={t("Write the decision, blocker, or question...", "اكتب القرار أو العائق أو السؤال...")} aria-label={t("Ask the AI coach", "اسأل مساعد الذكاء الاصطناعي")} /><div><span className="mono">{t("Your context stays with your account", "يبقى سياقك مع حسابك")}</span><button className="button button-primary" type="submit">{t("Send to coach", "أرسل إلى المساعد")} <ArrowRight size={14} /></button></div></form></div></ProductShell>;
}

function FounderProfileWorkspace() {
  const { t, formatNum } = useLocale();
  const [saved, setSaved] = useState(false);
  const [interests, setInterests] = useState([t("Pricing", "التسعير"), t("Customer discovery", "اكتشاف العملاء")]);
  const [photo, setPhoto] = useState("");
  const [signal, setSignal] = useState(t("Building a calmer way for founders to find practical help.", "أبني طريقة أهدأ للمؤسسين للعثور على مساعدة عملية."));
  const [context, setContext] = useState(t("I am validating a workflow for early-stage SaaS teams across MENA.", "أختبر سير عمل لفرق البرمجيات في مراحلها المبكرة في المنطقة."));
  const [stage, setStage] = useState("Idea");
  const [visibility, setVisibility] = useState<"network" | "matches">("network");
  const removeInterest = (tag: string) => setInterests((current) => current.filter((item) => item !== tag));
  const addInterest = () => { const value = window.prompt(t("Add an operating interest", "أضف اهتماما تشغيليا")); if (value?.trim()) setInterests((current) => [...current, value.trim()]); };
  const changePhoto = (event: ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; event.target.value = ""; if (!file || !file.type.startsWith("image/")) return; const reader = new FileReader(); reader.onload = () => setPhoto(reader.result as string); reader.readAsDataURL(file); };
  const portrait = photo ? <img src={photo} alt="" /> : <span>SA</span>;
  return <ProductShell title={t("My profile", "ملفي الشخصي")} active="/dashboard/profile"><div className="founder-profile-command">
    <header className="founder-profile-command__masthead"><div><SectionLabel>{t("Founder identity / shareable context", "هوية المؤسس / سياق قابل للمشاركة")}</SectionLabel><h1>{t("Give the network enough context to be useful.", "امنح الشبكة سياقا كافيا لتكون مفيدة.")}</h1><p>{t("This is not a public bio. It is the working context that helps the right people, rooms, and resources make sense of your next move.", "هذا ليس نبذة عامة. بل هو السياق العملي الذي يساعد الأشخاص والمساحات والموارد المناسبة على فهم خطوتك التالية.")}</p></div><div className="founder-profile-command__state"><span className="mono">{t("PROFILE SIGNAL", "إشارة الملف")}</span><strong>{formatNum("84")}</strong><small>{t("% complete", "٪ مكتمل")}</small><div><i /><i /><i className="is-empty" /><i className="is-empty" /></div></div></header>
    <section className="founder-profile-identity"><div className="founder-profile-identity__person"><div className="founder-profile-portrait">{portrait}<label>{t("Change", "تغيير")}<input type="file" accept="image/*" onChange={changePhoto} /></label></div><div><span className="mono">{t("FOUNDER / CAIRO", "مؤسسة / القاهرة")}</span><h2>Sara Ammar</h2><p>{t("Idea stage · B2B SaaS", "مرحلة الفكرة · برمجيات B2B")}</p><div className="founder-profile-identity__tags"><span>{t("MENA", "المنطقة")}</span><span>{t("Founder", "مؤسس")}</span><span>{t("Building in public", "البناء علنا")}</span></div></div></div><div className="founder-profile-identity__signal"><span className="mono">{t("THE LINE PEOPLE SEE FIRST", "السطر الذي يراه الناس أولا")}</span><textarea value={signal} onChange={(event) => setSignal(event.target.value)} aria-label={t("One-line founder signal", "إشارة المؤسس في سطر واحد")} /><small>{t("Use the specific work, not the broad ambition.", "استخدم العمل المحدد، لا الطموح العام.")}</small></div></section>
    <section className="founder-profile-context-grid"><form className="founder-profile-context" onSubmit={(event) => { event.preventDefault(); setSaved(true); }}><div className="founder-profile-section-heading"><div><SectionLabel>{t("Operating context", "السياق التشغيلي")}</SectionLabel><h2>{t("The details that shape a useful match.", "التفاصيل التي تشكل تطابقا مفيدا.")}</h2></div><span>{t("Used privately across matching", "تستخدم بشكل خاص عبر المطابقة")}</span></div><div className="founder-profile-field-grid"><label><span>{t("Company stage", "مرحلة الشركة")}</span><select value={stage} onChange={(event) => setStage(event.target.value)}><option value="Idea">{t("Idea / validation", "فكرة / تحقق")}</option><option value="First revenue">{t("First revenue", "أول إيراد")}</option><option value="Growth">{t("Growth motion", "حركة نمو")}</option></select></label><label><span>{t("Closest market", "السوق الأقرب")}</span><select defaultValue="Egypt"><option>{t("Egypt", "مصر")}</option><option>{t("GCC", "الخليج")}</option><option>{t("Levant", "المشرق")}</option><option>{t("Multiple MENA markets", "أسواق متعددة في المنطقة")}</option></select></label><label className="span-two"><span>{t("What I am working on", "ما أعمل عليه")}</span><textarea value={context} onChange={(event) => setContext(event.target.value)} /></label></div><div className="founder-profile-interests"><div><span className="mono">{t("OPERATING INTERESTS", "الاهتمامات التشغيلية")}</span><p>{t("Signals that shape the people and field notes you see first.", "إشارات تشكل الأشخاص والملاحظات الميدانية التي تراها أولا.")}</p></div><div>{interests.map((tag) => <button type="button" key={tag} onClick={() => removeInterest(tag)}>{tag} <X size={12} /></button>)}<button type="button" className="founder-profile-add" onClick={addInterest}><Plus size={12} /> {t("Add focus", "أضف تركيزا")}</button></div></div><div className="founder-profile-save"><button className="button button-primary" type="submit">{saved ? t("Context saved", "تم حفظ السياق") : t("Save founder context", "احفظ سياق المؤسس")} <Check size={14} /></button>{saved && <span><Check size={13} /> {t("Your matching signal has been refreshed.", "تم تحديث إشارة المطابقة الخاصة بك.")}</span>}</div></form><aside className="founder-profile-readout"><div className="founder-profile-readout__head"><SectionLabel light>{t("How the network reads this", "كيف تقرأ الشبكة هذا")}</SectionLabel><span className="mono">{visibility === "network" ? t("NETWORK", "الشبكة") : t("MATCHES", "التطابقات")}</span></div><div className="founder-profile-readout__card"><div className="founder-profile-readout__person"><span>{photo ? <img src={photo} alt="" /> : "SA"}</span><div><strong>Sara Ammar</strong><small>{t("Founder · Cairo", "مؤسسة · القاهرة")}</small></div></div><p>“{signal}”</p><div className="founder-profile-readout__meta"><span>{stage === "Idea" ? t("Idea stage", "مرحلة الفكرة") : stage === "First revenue" ? t("First revenue", "أول إيراد") : t("Growth", "نمو")}</span><span>{interests[0]}</span></div></div><div className="founder-profile-visibility"><span className="mono">{t("SHARING LEVEL", "مستوى المشاركة")}</span><button type="button" className={visibility === "network" ? "is-active" : ""} onClick={() => setVisibility("network")}><span><strong>{t("Visible to the network", "مرئي للشبكة")}</strong><small>{t("People can understand the signal before they connect.", "يمكن للأشخاص فهم الإشارة قبل التواصل.")}</small></span>{visibility === "network" && <Check size={15} />}</button><button type="button" className={visibility === "matches" ? "is-active" : ""} onClick={() => setVisibility("matches")}><span><strong>{t("Only in recommended matches", "فقط في التطابقات المقترحة")}</strong><small>{t("Keep operating context inside curated introductions.", "أبقِ السياق التشغيلي داخل المقدمات المنتقاة.")}</small></span>{visibility === "matches" && <Check size={15} />}</button></div></aside></section>
    <section className="founder-profile-handoff"><div><SectionLabel>{t("Signal handoff", "تسليم الإشارة")}</SectionLabel><h2>{t("This context now shapes what reaches you next.", "هذا السياق يشكل الآن ما يصل إليك تاليا.")}</h2></div><div><article><span>{formatNum("02")}</span><strong>{t("People matched to your current question", "أشخاص مطابقون لسؤالك الحالي")}</strong><Link href="/matching">{t("Open matching", "افتح المطابقة")} <ArrowRight size={13} /></Link></article><article><span>{formatNum("01")}</span><strong>{t("Event room built for your operating stage", "غرفة فعاليات مبنية لمرحلتك التشغيلية")}</strong><Link href="/dashboard/events">{t("See events", "شاهد الفعاليات")} <ArrowRight size={13} /></Link></article><article><span>{formatNum("03")}</span><strong>{t("Field notes worth using before the next move", "ملاحظات ميدانية تستحق الاستخدام قبل الخطوة التالية")}</strong><Link href="/learn">{t("Open learning", "افتح التعلم")} <ArrowRight size={13} /></Link></article></div></section>
  </div></ProductShell>;
}

