function SettingsWorkspace() {
  const { t } = useLocale();
  const { logout } = useAuth();
  const [, setLocation] = useLocation();
  const [saved, setSaved] = useState(false);
  const [weekly, setWeekly] = useState(true);
  const [eventReminders, setEventReminders] = useState(true);
  const { message, showToast, clearToast } = useToast();
  const deleteAccount = () => {
    if (window.confirm(t("Delete your ASaaSI account? This removes your profile, saved items, and requests. This cannot be undone.", "حذف حسابك في أساسي؟ سيؤدي ذلك إلى إزالة ملفك الشخصي والعناصر المحفوظة والطلبات. لا يمكن التراجع عن هذا."))) {
      logout();
      setLocation("/");
    }
  };
  return <ProductShell title={t("Settings", "الإعدادات")} active="/dashboard/settings"><div className="product-page-heading compact"><div><SectionLabel>{t("Settings / Control panel", "الإعدادات / لوحة التحكم")}</SectionLabel><h1>{t("Keep the product working in your favor.", "أبقِ المنتج يعمل لصالحك.")}</h1><p>{t("Privacy, notifications, and account controls live here. No mystery switches.", "الخصوصية والإشعارات وضوابط الحساب موجودة هنا. لا مفاتيح غامضة.")}</p></div></div><div className="settings-grid"><section className="settings-panel"><SectionLabel>{t("Notifications", "الإشعارات")}</SectionLabel><h2>{t("Choose the signal, not the noise.", "اختر الإشارة، لا الضجيج.")}</h2><label className="toggle-row"><span><strong>{t("Weekly founder brief", "موجز المؤسس الأسبوعي")}</strong><small>{t("One useful summary of events, people, and ideas.", "ملخص مفيد واحد للفعاليات والأشخاص والأفكار.")}</small></span><button className={`toggle ${weekly ? "on" : ""}`} onClick={() => setWeekly(!weekly)} aria-pressed={weekly}><span /></button></label><label className="toggle-row"><span><strong>{t("Event reminders", "تذكيرات الفعاليات")}</strong><small>{t("Only for events you saved or joined.", "للفعاليات التي حفظتها أو انضممت إليها فقط.")}</small></span><button className={`toggle ${eventReminders ? "on" : ""}`} onClick={() => setEventReminders(!eventReminders)} aria-pressed={eventReminders}><span /></button></label></section><section className="settings-panel"><SectionLabel>{t("Account", "الحساب")}</SectionLabel><h2>{t("One identity, clear boundaries.", "هوية واحدة، وحدود واضحة.")}</h2><button className="settings-link" onClick={() => showToast(t("Email editing opens here in the full product.", "سيفتح تعديل البريد الإلكتروني هنا في المنتج الكامل."))}>{t("Edit email", "عدل البريد الإلكتروني")} <ChevronRight size={15} /></button><button className="settings-link" onClick={() => showToast(t("Password change opens here in the full product.", "سيفتح تغيير كلمة المرور هنا في المنتج الكامل."))}>{t("Change password", "غير كلمة المرور")} <ChevronRight size={15} /></button><button className="settings-link" onClick={() => showToast(t("Your data export would start here in the full product.", "سيبدأ تصدير بياناتك هنا في المنتج الكامل."))}>{t("Download my data", "نزل بياناتي")} <Download size={15} /></button><button className="settings-link danger" onClick={deleteAccount}>{t("Delete account", "احذف الحساب")} <ChevronRight size={15} /></button></section></div><button className="button button-primary" onClick={() => setSaved(true)}>{saved ? t("Settings saved", "تم حفظ الإعدادات") : t("Save changes", "احفظ التغييرات")} <Check size={14} /></button>{message && <Toast message={message} onClose={clearToast} />}</ProductShell>;
}

