export function SignupFlow() {
  const { t } = useLocale();
  const { login } = useAuth();
  const [step, setStep] = useState(0);
  const [roles, setRoles] = useState<string[]>(["Founder"]);
  const roleOptions = [["Founder", "مؤسس"], ["Mentor / expert", "مرشد / خبير"], ["SaaS professional", "متخصص برمجيات"], ["Aspiring founder", "مؤسس طموح"], ["Investor", "مستثمر"], ["Service provider", "مزود خدمة"]] as const;
  const stageOptions = [["Idea", "فكرة"], ["Pre-revenue", "قبل الإيرادات"], ["$0-10K ARR", "٠-١٠ آلاف دولار إيراد سنوي"], ["$10K-100K ARR", "١٠-١٠٠ ألف دولار إيراد سنوي"]] as const;
  const params = typeof window === "undefined" ? new URLSearchParams() : new URLSearchParams(window.location.search);
  const intent = params.get("intent");
  const eventSlug = params.get("event");
  const workspaceHref = intent === "register" && eventSlug ? `/events/${eventSlug}` : "/dashboard";
  useEffect(() => { if (step === 3) login(); }, [step]);
  return <div className="signup-flow"><div className="signup-topbar"><Link href="/"><Logo /></Link><span className="mono">{t("Founder signal", "إشارة المؤسس")} / {step + 1} {t("of", "من")} 4</span><Link href="/login" className="text-link">{t("Already a member? Log in", "عضو بالفعل؟ سجل الدخول")}</Link></div><div className="signup-grid"><aside className="signup-aside"><SectionLabel light>{t("Build your signal", "ابنِ إشارتك")}</SectionLabel><h1>{t("Start with where you are, not where you think you should be.", "ابدأ من مكانك، لا من المكان الذي تظن أنه يجب أن تكون فيه.")}</h1><p>{t("One identity, and the whole MENA SaaS ecosystem already knows your stage, people, events, learning, and tools.", "هوية واحدة، ومنظومة برمجيات المنطقة بأكملها تعرف مرحلتك بالفعل، الأشخاص والفعاليات والتعلم والأدوات.")}</p>{(intent === "save-event" || intent === "register") && <div className="status-banner"><div><strong>{t("Signing up also unlocks this:", "التسجيل يفتح لك هذا أيضا:")}</strong><p>{t("Personalized event recommendations based on your interests, and every saved or registered event stays in your workspace.", "توصيات فعاليات مخصصة بناء على اهتماماتك، وتبقى كل فعالية محفوظة أو مسجَلة في مساحة عملك.")}</p></div></div>}<div className="signup-trail">{[t("Account", "الحساب"), t("Roles", "الأدوار"), t("Context", "السياق"), t("Ready", "جاهز")].map((label, index) => <span className={index === step ? "active" : index < step ? "done" : ""} key={label}>{String(index + 1).padStart(2, "0")} {label}</span>)}</div></aside><main className="signup-card"><div className="signup-card-top"><SectionLabel>{step === 0 ? t("Identity", "الهوية") : step === 1 ? t("Roles", "الأدوار") : step === 2 ? t("Context", "السياق") : t("Your workspace", "مساحة عملك")}</SectionLabel><span className="mono">{Math.round(((step + 1) / 4) * 100)}%</span></div>{step === 0 && <div className="signup-step"><h2>{t("Who should we recognize?", "من نعرف؟")}</h2><p>{t("Use the email you want attached to your founder identity.", "استخدم البريد الذي تريد ربطه بهوية مؤسسك.")}</p><label>{t("Full name", "الاسم الكامل")}<input placeholder={t("Your name", "اسمك")} /></label><label>{t("Work email", "بريد العمل")}<input type="email" placeholder="you@company.com" /></label><label>{t("Password", "كلمة المرور")}<input type="password" placeholder={t("At least 8 characters", "٨ أحرف على الأقل")} /></label><button className="button button-primary" onClick={() => setStep(1)}>{t("Continue", "تابع")} <ArrowRight size={14} /></button></div>}{step === 1 && <div className="signup-step"><h2>{t("What brings you here?", "ما الذي جاء بك إلى هنا؟")}</h2><p>{t("Pick everything that is true. You can change this later.", "اختر كل ما ينطبق. يمكنك تغيير ذلك لاحقا.")}</p><div className="role-options">{roleOptions.map((role) => <button className={roles.includes(role[0]) ? "role-option selected" : "role-option"} onClick={() => setRoles(roles.includes(role[0]) ? roles.filter((r) => r !== role[0]) : [...roles, role[0]])} key={role[0]}><span>{t(role[0], role[1])}</span>{roles.includes(role[0]) && <Check size={15} />}</button>)}</div><div className="signup-nav"><button className="button button-ghost" onClick={() => setStep(0)}><ArrowLeft size={14} /> {t("Back", "رجوع")}</button><button className="button button-primary" onClick={() => setStep(2)}>{t("Continue", "تابع")} <ArrowRight size={14} /></button></div></div>}{step === 2 && <div className="signup-step"><h2>{t("Give us one useful detail.", "أعطنا تفصيلا مفيدا واحدا.")}</h2><p>{t("This changes the events and people we recommend first.", "هذا يغير الفعاليات والأشخاص الذين نوصي بهم أولا.")}</p><label>{t("Where are you right now?", "أين أنت الآن؟")}<select defaultValue="Idea">{stageOptions.map((stage) => <option key={stage[0]} value={stage[0]}>{t(stage[0], stage[1])}</option>)}</select></label><label>{t("What is taking most of your attention?", "ما الذي يستحوذ على معظم انتباهك؟")}<textarea placeholder={t("e.g. finding my first repeatable channel", "مثلا: العثور على أول قناة قابلة للتكرار")} /></label><label>{t("Where do you work from?", "من أين تعمل؟")}<input placeholder={t("Cairo, Egypt", "القاهرة، مصر")} /></label><div className="signup-nav"><button className="button button-ghost" onClick={() => setStep(1)}><ArrowLeft size={14} /> {t("Back", "رجوع")}</button><button className="button button-primary" onClick={() => setStep(3)}>{t("Build my signal", "ابنِ إشارتك")} <ArrowRight size={14} /></button></div></div>}{step === 3 && <div className="signup-step signup-complete"><div className="complete-node"><Check size={22} /></div><SectionLabel>{t("Your signal is ready", "إشارتك جاهزة")}</SectionLabel><h2>{t("There is a shorter path now.", "هناك طريق أقصر الآن.")}</h2><p>{t("We’ll start you with one pricing brief, two people worth meeting, and the next useful event.", "سنبدأ معك بموجز تسعير واحد وشخصين يستحقان اللقاء والفعالية المفيدة التالية.")}</p><Link href={workspaceHref} className="button button-primary">{eventSlug ? t("Back to the event", "العودة إلى الفعالية") : t("Enter my workspace", "ادخل مساحة عملي")} <ArrowRight size={14} /></Link></div>}</main></div></div>;
}

const requestTypeOptions = [
  ["Find an advisor", "ابحث عن مستشار"], ["Hire talent", "وظف موهبة"], ["Find a cofounder", "ابحث عن شريك مؤسس"], ["Get customers", "احصل على عملاء"],
] as const;

export function RequestFlow() {
  const { t } = useLocale();
  const [sent, setSent] = useState(false);
  const [type, setType] = useState("Find an advisor");
  const [audience, setAudience] = useState("Relevant members");
  const [safetyChecked, setSafetyChecked] = useState(true);
  const [subscriber] = useState(() => typeof window !== "undefined" && window.localStorage.getItem("asaasi-access-tier") === "subscriber");
  const [openRequests, setOpenRequests] = useState(() => typeof window === "undefined" ? 0 : Number(window.localStorage.getItem("asaasi-open-requests") || 0));
  const capped = !subscriber && openRequests >= 1;
  const typeLabel = requestTypeOptions.find(([en]) => en === type) ?? requestTypeOptions[0];
  const publish = () => {
    if (!safetyChecked || capped) return;
    const next = openRequests + 1;
    window.localStorage.setItem("asaasi-open-requests", String(next));
    setOpenRequests(next);
    setSent(true);
  };
  return <ProductShell title={t("Ask the network", "اسأل الشبكة")} active="/dashboard/requests"><div className="product-page-heading compact"><div><SectionLabel>{t("Requests / Focused ask", "الطلبات / سؤال مركز")}</SectionLabel><h1>{t("Say what would make the next week easier.", "قل ما الذي سيجعل الأسبوع القادم أسهل.")}</h1><p>{t("Requests carry one consistent lifecycle: draft, review, matched, response received, and closed. Start with an outcome someone can genuinely help move.", "تمر الطلبات بدورة حياة واحدة ثابتة: مسودة، مراجعة، مطابقة، استلام رد، وإغلاق. ابدأ بنتيجة يمكن لشخص ما مساعدتك فعلا في تحريكها.")}</p></div><SignalTag tone={subscriber ? "yellow" : "clay"}>{subscriber ? t("Member · Unlimited requests", "عضو · طلبات غير محدودة") : t(`Free Member · ${Math.min(openRequests, 1)} of 1 open request used`, `عضو مجاني · ${Math.min(openRequests, 1)} من طلب مفتوح واحد مستخدم`)}</SignalTag></div>{sent ? <div className="success-state"><div className="complete-node"><Check size={22} /></div><SectionLabel>{t("Request published / matching", "تم نشر الطلب / قيد المطابقة")}</SectionLabel><h2>{t("Your ask has a clear next state.", "أصبح لطلبك حالة تالية واضحة.")}</h2><p>{t("It is private to the audience you chose. ASaaSI will first surface members whose profile context suggests they can offer a useful response.", "الطلب خاص بالجمهور الذي اخترته. سيعرض أساسي أولا الأعضاء الذين يشير سياق ملفهم إلى قدرتهم على تقديم رد مفيد.")}</p><div className="request-status-timeline"><span className="complete">{t("Draft", "مسودة")}</span><span className="complete">{t("Published", "منشور")}</span><span className="current">{t("Matching", "مطابقة")}</span><span>{t("Response", "رد")}</span><span>{t("Closed", "مغلق")}</span></div><div className="product-actions"><Link href="/dashboard/requests" className="button button-dark">{t("View my requests", "شاهد طلباتي")} <ArrowRight size={14} /></Link>{subscriber && <button type="button" className="button button-ghost" onClick={() => setSent(false)}>{t("Create another", "أنشئ طلبا آخر")}</button>}</div></div> : capped ? <div className="empty-state"><LockKeyhole size={20} /><h2>{t("Free tier limit reached.", "وصلت إلى حد الفئة المجانية.")}</h2><p>{t("Free members can keep one open request at a time. Close it or upgrade to publish another.", "يمكن للأعضاء المجانيين إبقاء طلب مفتوح واحد فقط. أغلقه أو رقِّ عضويتك لنشر طلب آخر.")}</p><Link href="/dashboard/requests" className="button button-ghost">{t("View my open request", "شاهد طلبي المفتوح")}</Link><Link href="/dashboard/billing" className="button button-dark">{t("Upgrade to Member", "رقِّ إلى عضوية Member")} <ArrowRight size={14} /></Link></div> : <div className="request-compose"><div className="request-types"><span className="mono">{t("I want to", "أريد أن")}</span>{requestTypeOptions.map(([en, ar]) => <button type="button" className={en === type ? "request-type active" : "request-type"} onClick={() => setType(en)} key={en}>{t(en, ar)}<ChevronRight size={14} /></button>)}</div><form className="request-form" onSubmit={(event) => { event.preventDefault(); publish(); }}><SectionLabel>{t("Request", "طلب")} / {t(typeLabel[0], typeLabel[1])}</SectionLabel><h2>{t("Make the ask easy to answer.", "اجعل الطلب سهل الإجابة.")}</h2><label>{t("What outcome do you need?", "ما النتيجة التي تحتاجها؟")}<input required placeholder={type === "Find an advisor" ? t("e.g. a second opinion on usage-based pricing", "مثلا: رأي ثانٍ حول التسعير القائم على الاستخدام") : t("Write the specific outcome you want", "اكتب النتيجة المحددة التي تريدها")} /></label><label>{t("Why now?", "لماذا الآن؟")}<textarea required placeholder={t("Give enough context for the right person to recognize the problem and the kind of response that would help.", "أعطِ سياقا كافيا ليتعرف الشخص المناسب على المشكلة ونوع الرد الذي قد يساعد.")} /></label><div className="two-fields"><label>{t("Stage", "المرحلة")}<select defaultValue="Idea"><option>{t("Idea", "فكرة")}</option><option>{t("Pre-revenue", "ما قبل الإيراد")}</option><option>{t("Early revenue", "إيراد مبكر")}</option><option>{t("Growth", "نمو")}</option></select></label><label>{t("Location", "الموقع")}<input placeholder={t("Cairo / Online", "القاهرة / عبر الإنترنت")} /></label></div><label>{t("Who should see it?", "من يجب أن يراه؟")}<select value={audience} onChange={(event) => setAudience(event.target.value)}><option>{t("Relevant members", "الأعضاء ذوو الصلة")}</option><option>{t("My organization only", "منظمتي فقط")}</option><option>{t("Invite-only introductions", "مقدمات بدعوة فقط")}</option></select></label><label className="checkbox-label request-check"><input type="checkbox" checked={safetyChecked} onChange={(event) => setSafetyChecked(event.target.checked)} /> {t("I have removed confidential customer data and I am asking for a focused, professional response.", "لقد أزلت بيانات العملاء السرية وأطلب ردا مركزا ومهنيا.")}</label><div className="form-footer"><span className="mono">{subscriber ? t("Unlimited as a Member", "غير محدود كعضو") : t("Free tier: 1 open request at a time", "الفئة المجانية: طلب مفتوح واحد في كل مرة")}</span><button className="button button-primary" type="submit" disabled={!safetyChecked}>{t("Publish focused ask", "انشر السؤال المركز")} <ArrowRight size={14} /></button></div>{!safetyChecked && <p className="form-error">{t("Confirm the request guidance before publishing.", "أكد إرشادات الطلب قبل النشر.")}</p>}</form></div>}</ProductShell>;
}

export function MatchingWorkspace() {
  const { t, isRTL, formatNum } = useLocale();
  const [query, setQuery] = useState("");
  const [filterOpen, setFilterOpen] = useState(false);
  const [stage, setStage] = useState("All stages");
  const [focus, setFocus] = useState("All focus areas");
  const [selectedName, setSelectedName] = useState<string | null>(null);
  const [saved, setSaved] = useState<string[]>([]);
  const [introRequested, setIntroRequested] = useState(false);
  const filtered = people.filter((person) => `${person.name} ${person.role} ${person.reason} ${person.focus}`.toLowerCase().includes(query.toLowerCase()) && (stage === "All stages" || person.stage === stage) && (focus === "All focus areas" || person.focus === focus));
  const selected = people.find((person) => person.name === selectedName);
  const selectedIndex = selected ? people.indexOf(selected) + 1 : 1;
  const toggleSaved = (name: string) => setSaved((current) => current.includes(name) ? current.filter((item) => item !== name) : [...current, name]);
  const activeFilterCount = Number(stage !== "All stages") + Number(focus !== "All focus areas");
  const stageWord = stage === "All stages" ? null : t(stage, stageLabels[stage]);
  const focusWord = focus === "All focus areas" ? null : t(focus, focusLabels[focus]);
  const matchSentence = stageWord || focusWord
    ? <>{t("Looking for", "تبحث عن")} {stageWord && <strong>{stageWord}</strong>}{stageWord && focusWord && " · "}{focusWord && <strong>{focusWord}</strong>} {t("people", "أشخاص")}</>
    : <>{t("Showing", "يظهر لك")} <strong>{t("everyone in your orbit", "كل من في مدارك")}</strong></>;
  return <ProductShell title={t("Find people", "ابحث عن أشخاص")} active="/matching"><div className="product-page-heading compact"><div><SectionLabel>{t("Matching / Your orbit", "المطابقة / مدارك")}</SectionLabel><h1>{t("Find the person who has already wrestled with this.", "اعثر على الشخص الذي خاض هذا التحدي من قبل.")}</h1><p>{t("We start with your founder stage and live decision, then show the reasoning behind every useful introduction.", "نبدأ بمرحلة مؤسسك وقرارك الحالي، ثم نوضح منطق كل مقدمة مفيدة.")}</p></div></div><div className="match-sentence-card"><p className="match-sentence">{matchSentence}</p><div className="match-sentence-proof"><div className="match-sentence-avatars">{filtered.slice(0, 3).map((person) => <span className={`match-sentence-avatar avatar-${person.tone}`} key={person.name} title={person.name}>{person.initials}</span>)}</div><span className="match-sentence-count"><strong>{formatNum(filtered.length)}</strong> {t(filtered.length === 1 ? "close match" : "close matches", "مطابقات قريبة")}</span></div></div><div className="matching-toolbar"><div className="search-field"><Search size={16} /><label className="sr-only" htmlFor="match-search">{t("Search matches", "ابحث في المطابقات")}</label><input id="match-search" value={query} onChange={(event) => setQuery(event.target.value)} placeholder={t("Search by problem, role, or name", "ابحث بالمشكلة أو الدور أو الاسم")} /></div><button type="button" className={`button button-ghost ${filterOpen ? "is-active" : ""}`} aria-expanded={filterOpen} aria-controls="matching-filters" onClick={() => setFilterOpen((open) => !open)}>{t("Filter", "تصفية")} {activeFilterCount ? `(${activeFilterCount})` : ""} <MoreHorizontal size={15} /></button>{filterOpen && <div className="match-filter-menu" id="matching-filters"><span className="mono">{t("Narrow the signal", "ضيق الإشارة")}</span><label>{t("Founder stage", "مرحلة المؤسس")}<select value={stage} onChange={(event) => setStage(event.target.value)}><option value="All stages">{t("All stages", "كل المراحل")}</option><option value="Validate">{t("Validate", stageLabels.Validate)}</option><option value="Build">{t("Build", stageLabels.Build)}</option><option value="Scale">{t("Scale", stageLabels.Scale)}</option></select></label><label>{t("Focus area", "مجال التركيز")}<select value={focus} onChange={(event) => setFocus(event.target.value)}><option value="All focus areas">{t("All focus areas", "كل مجالات التركيز")}</option><option value="Pricing systems">{t("Pricing systems", focusLabels["Pricing systems"])}</option><option value="Enterprise motion">{t("Enterprise motion", focusLabels["Enterprise motion"])}</option><option value="Product discovery">{t("Product discovery", focusLabels["Product discovery"])}</option></select></label><button type="button" className="text-link" onClick={() => { setStage("All stages"); setFocus("All focus areas"); }}>{t("Clear filters", "امسح التصفية")} <X size={14} /></button></div>}</div>{filtered.length ? <div className="match-grid">{filtered.map((person) => <article className="match-card" key={person.name}><div className={`orbit-avatar avatar-${person.tone}`}>{person.initials}</div><SectionLabel>{t(person.city, person.cityAr)} / {t(person.stage, stageLabels[person.stage] ?? person.stage)}</SectionLabel><h2>{person.name}</h2><p className="match-role">{t(person.role, person.roleAr)}</p><p>{t(person.reason, person.reasonAr)}</p><div className="match-footer"><button type="button" className="button button-dark" onClick={() => { setSelectedName(person.name); setIntroRequested(false); }}>{t("Review fit", "راجع الملاءمة")} <ArrowRight size={14} /></button><button type="button" className={`icon-button ${saved.includes(person.name) ? "is-saved" : ""}`} aria-pressed={saved.includes(person.name)} aria-label={t(`${saved.includes(person.name) ? "Remove" : "Save"} ${person.name}`, `${saved.includes(person.name) ? "إزالة" : "حفظ"} ${person.name}`)} onClick={() => toggleSaved(person.name)}><Save size={15} /></button></div>{saved.includes(person.name) && <span className="action-feedback" role="status"><Check size={13} /> {t("Saved to your shortlist", "تم الحفظ في قائمتك المختصرة")}</span>}</article>)}</div> : <div className="empty-state"><h2>{t("No people match this signal yet.", "لا يوجد أشخاص يطابقون هذه الإشارة بعد.")}</h2><p>{t("Try widening the stage, focus area, or search phrase.", "جرب توسيع المرحلة أو مجال التركيز أو عبارة البحث.")}</p><button type="button" className="button button-dark" onClick={() => { setQuery(""); setStage("All stages"); setFocus("All focus areas"); }}>{t("Clear search and filters", "امسح البحث والتصفية")}</button></div>}<Drawer direction={isRTL ? "left" : "right"} open={Boolean(selected)} onOpenChange={(open) => { if (!open) setSelectedName(null); }}><DrawerContent className="fit-review-drawer"><DrawerHeader className="fit-review-header"><div><span className="mono">{t("Match review / explainable fit", "مراجعة المطابقة / ملاءمة قابلة للتفسير")}</span><DrawerTitle>{selected?.name ?? t("Match review", "مراجعة المطابقة")}</DrawerTitle><DrawerDescription>{selected ? `${t(selected.role, selected.roleAr)} · ${t(selected.city, selected.cityAr)}` : ""}</DrawerDescription></div><DrawerClose asChild><button type="button" className="icon-button" aria-label={t("Close fit review", "إغلاق مراجعة المطابقة")}><X size={16} /></button></DrawerClose></DrawerHeader>{selected && <div className="fit-review-body"><div className={`fit-review-avatar orbit-avatar avatar-${selected.tone}`}>{selected.initials}</div><section><SectionLabel>{t("Why this may fit", "لماذا قد تكون هذه مطابقة مناسبة")}</SectionLabel><div className="fit-signal-row"><span className="fit-signal-count">{formatNum(3)}/{formatNum(3)} {t("signals matched", "إشارات متطابقة")}</span><span className="fit-signal-chip">{t("Shared decision", "قرار مشترك")}</span><span className="fit-signal-chip">{t("Relevant stage", "مرحلة ذات صلة")}</span><span className="fit-signal-chip">{t("Specific context", "سياق محدد")}</span></div><div className="fit-reason-list"><div><span>01</span><p><strong>{t("Shared decision:", "قرار مشترك:")}</strong> {t("your current pricing brief needs an operator who has seen B2B packaging become repeatable.", "يحتاج موجز التسعير الحالي إلى مشغل رأى تغليف البرمجيات للشركات يتحول إلى عملية قابلة للتكرار.")}</p></div><div><span>02</span><p><strong>{t("Relevant stage:", "مرحلة ذات صلة:")}</strong> {t(`${selected.name.split(" ")[0]} is most active around the ${selected.stage.toLowerCase()} work you are doing now.`, `${selected.name.split(" ")[0]} ينشط أكثر حول عمل ${stageLabels[selected.stage] ?? selected.stage} الذي تقوم به الآن.`)}</p></div><div><span>03</span><p><strong>{t("Specific context:", "سياق محدد:")}</strong> {t(selected.reason, selected.reasonAr)}.</p></div></div></section><section className="fit-boundary"><span className="mono">{t("A good introduction is specific", "المقدمة الجيدة محددة")}</span><strong>{t("Send one question about your pricing decision, not a general request for mentorship.", "أرسل سؤالا واحدا عن قرار التسعير، لا طلبا عاما للإرشاد.")}</strong></section>{introRequested && <div className="inline-success" role="status"><Check size={15} /> {t("Introduction request drafted with your founder brief attached.", "تم إعداد طلب المقدمة وإرفاق موجز مؤسسك.")}</div>}</div>}<DrawerFooter className="fit-review-footer">{selected && <Link href={`/dashboard/members/${selectedIndex}`} className="button button-light">{t("Open full profile", "افتح الملف الكامل")} <ArrowRight size={14} /></Link>}<button type="button" className="button button-primary" onClick={() => setIntroRequested(true)}>{introRequested ? t("Request ready", "الطلب جاهز") : t("Request introduction", "اطلب مقدمة")} <ArrowRight size={14} /></button></DrawerFooter></DrawerContent></Drawer></ProductShell>;
}

const orgRoleOptions = [["Founder / Owner", "مؤسس / مالك"], ["Operator / Team member", "مشغل / عضو فريق"], ["Advisor / Mentor", "مستشار / مرشد"], ["Operations / Finance", "عمليات / مالية"]] as const;
const orgTabOptions = [["Overview", "نظرة عامة"], ["People", "الأشخاص"], ["Requests", "الطلبات"], ["Settings", "الإعدادات"]] as const;

export function OrganizationFlow({ mode = "new" }: { mode?: "new" | "join" | "workspace" }) {
  const { t } = useLocale();
  const [sent, setSent] = useState(false);
  const [tab, setTab] = useState("Overview");
  const [role, setRole] = useState("Founder / Owner");
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const readiness = [name.trim().length > 1, description.trim().length > 15, role.length > 0].filter(Boolean).length;
  const roleLabel = orgRoleOptions.find(([en]) => en === role) ?? orgRoleOptions[0];
  if (mode === "workspace") return <ProductShell title={t("Organization workspace", "مساحة عمل المنظمة")} active="/dashboard/organizations"><div className="org-workspace"><div className="org-banner"><div className="org-logo">AL</div><div><SectionLabel light>{t("Organization / active context", "المنظمة / السياق النشط")}</SectionLabel><h1>Atlas Labs</h1><p>{t("One ASaaSI identity", "هوية واحدة في أساسي")} · {t("3 active members", "٣ أعضاء نشطين")} · {t("Cairo", "القاهرة")} · {t("SaaS analytics", "تحليلات برمجيات")}</p></div><SignalTag tone="yellow">{t(roleLabel[0], roleLabel[1])}</SignalTag></div><div className="organization-identity"><span className="mono">{t("Your account role in this organization", "دورك في هذه المنظمة")}</span><div className="role-switcher">{orgRoleOptions.map(([en, ar]) => <button type="button" key={en} className={role === en ? "active" : ""} onClick={() => setRole(en)}>{t(en, ar)}</button>)}</div><p>{t("Changing organization context changes shared permissions, not your single personal member identity.", "تغيير سياق المنظمة يغير الصلاحيات المشتركة، لا هويتك الشخصية الواحدة كعضو.")}</p></div><div className="org-tabs">{orgTabOptions.map(([en, ar]) => <button type="button" key={en} className={tab === en ? "active" : ""} onClick={() => setTab(en)}>{t(en, ar)}{en === "People" && <span>3</span>}{en === "Requests" && <span>2</span>}</button>)}</div>{tab === "Overview" && <><div className="org-metrics"><div><span className="mono">{t("Open asks", "طلبات مفتوحة")}</span><strong>02</strong><p>{t("One needs a pricing operator.", "واحد يحتاج مشغل تسعير.")}</p></div><div><span className="mono">{t("Team signal", "إشارة الفريق")}</span><strong>74%</strong><p>{t("Profiles are ready for introductions.", "الملفات جاهزة للمقدمات.")}</p></div><div><span className="mono">{t("Next event", "الفعالية التالية")}</span><strong>{t("12 Nov", "١٢ نوفمبر")}</strong><p>{t("SaaS Summit MENA.", "قمة برمجيات المنطقة.")}</p></div></div><div className="org-activity"><SectionLabel>{t("Recent activity", "النشاط الأخير")}</SectionLabel><h2>{t("Keep the workspace moving.", "أبقِ مساحة العمل تتحرك.")}</h2><div className="activity-row"><span>SA</span><p><strong>{t("Sara", "سارة")}</strong> {t("created a pricing request.", "أنشأت طلب تسعير.")}<small>{t("Today · 09:10", "اليوم · ٠٩:١٠")}</small></p><ArrowRight size={14} /></div><div className="activity-row"><span>ON</span><p><strong>{t("Omar", "عمر")}</strong> {t("joined as a mentor.", "انضم كمرشد.")}<small>{t("Yesterday · context reviewed", "أمس · تمت مراجعة السياق")}</small></p><ArrowRight size={14} /></div></div></>}{tab === "People" && <section className="org-tab-panel"><SectionLabel>{t("People / roles", "الأشخاص / الأدوار")}</SectionLabel><h2>{t("One identity, clear organization roles.", "هوية واحدة، وأدوار منظمة واضحة.")}</h2><div className="org-member-list"><div><strong>Sara Ammar</strong><span>{t("Founder / Owner", "مؤسس / مالك")}</span><small>{t("Can manage roles, requests, and workspace settings.", "يمكنه إدارة الأدوار والطلبات وإعدادات مساحة العمل.")}</small></div><div><strong>Omar Nassar</strong><span>{t("Mentor", "مرشد")}</span><small>{t("Can respond to relevant organization requests.", "يمكنه الرد على طلبات المنظمة ذات الصلة.")}</small></div><div><strong>Lina Haddad</strong><span>{t("Team member", "عضو فريق")}</span><small>{t("Can participate in shared work and events.", "يمكنها المشاركة في العمل المشترك والفعاليات.")}</small></div></div></section>}{tab === "Requests" && <section className="org-tab-panel"><SectionLabel>{t("Requests / shared lifecycle", "الطلبات / دورة حياة مشتركة")}</SectionLabel><h2>{t("Keep requests accountable after they leave the draft.", "أبقِ الطلبات خاضعة للمساءلة بعد خروجها من مرحلة المسودة.")}</h2><div className="org-request-list"><div><strong>{t("Pricing operator for usage-based packaging", "مشغل تسعير لتغليف قائم على الاستخدام")}</strong><span className="status-pill current">{t("Matching", "مطابقة")}</span><small>{t("Published today · relevant mentors are being reviewed", "نُشر اليوم · تجري مراجعة المرشدين ذوي الصلة")}</small></div><div><strong>{t("First enterprise customer introductions", "أول مقدمات لعملاء مؤسسيين")}</strong><span className="status-pill">{t("Response received", "تم استلام الرد")}</span><small>{t("Owner review due tomorrow", "مراجعة المالك مستحقة غدا")}</small></div></div></section>}{tab === "Settings" && <section className="org-tab-panel"><SectionLabel>{t("Organization settings", "إعدادات المنظمة")}</SectionLabel><h2>{t("Permissions stay visible.", "تبقى الصلاحيات واضحة.")}</h2><p>{t("Owners manage membership and settings. Team members can collaborate. Mentors can respond only where the organization invites their expertise.", "يدير المالكون العضوية والإعدادات. يمكن لأعضاء الفريق التعاون. يمكن للمرشدين الرد فقط حيث تدعو المنظمة خبرتهم.")}</p></section>}</div></ProductShell>;
  return <ProductShell title={mode === "new" ? t("Create organization", "أنشئ منظمة") : t("Join organization", "انضم إلى منظمة")} active="/dashboard/organizations"><div className="product-page-heading compact"><div><SectionLabel>{t("Organizations", "المنظمات")} / {mode === "new" ? t("New workspace", "مساحة عمل جديدة") : t("Join a team", "انضم إلى فريق")}</SectionLabel><h1>{mode === "new" ? t("Give the company a space to grow in.", "امنح الشركة مساحة لتنمو فيها.") : t("Find the space your work already belongs in.", "اعثر على المساحة التي ينتمي إليها عملك بالفعل.")}</h1><p>{mode === "new" ? t("Create a shared context for your team, requests, and founder work. Your account stays one identity across every organization.", "أنشئ سياقا مشتركا لفريقك وطلباتك وعملك كمؤسس. يبقى حسابك هوية واحدة عبر كل منظمة.") : t("Enter a workspace code or describe your role so an owner can review the request with enough context.", "أدخل رمز مساحة العمل أو صف دورك ليتمكن المالك من مراجعة الطلب بسياق كافٍ.")}</p></div></div><form className="org-form panel-card" onSubmit={(event) => { event.preventDefault(); setSent(true); }}><div className="org-form-node"><span className={readiness >= 1 ? "active" : ""}>01</span><span className={readiness >= 2 ? "active" : ""}>02</span><span className={readiness >= 3 ? "active" : ""}>03</span></div><div className="org-readiness"><span className="mono">{t("Readiness", "الجاهزية")} / {t(`${readiness} of 3`, `${readiness} من ٣`)}</span><p>{readiness === 3 ? t("This workspace has enough context to be useful from the first invitation.", "لدى مساحة العمل هذه سياق كافٍ لتكون مفيدة من أول دعوة.") : t("Add a name, a clear context, and your role before continuing.", "أضف اسما وسياقا واضحا ودورك قبل المتابعة.")}</p></div><label>{mode === "new" ? t("Organization name", "اسم المنظمة") : t("Workspace code", "رمز مساحة العمل")}<input required value={name} onChange={(event) => setName(event.target.value)} placeholder={mode === "new" ? "Atlas Labs" : t("e.g. ATLAS-24", "مثلا: ATLAS-24")} /></label><label>{mode === "new" ? t("What are you building?", "ما الذي تبنيه؟") : t("Why are you joining?", "لماذا تنضم؟")}<textarea required value={description} onChange={(event) => setDescription(event.target.value)} placeholder={mode === "new" ? t("A one-line description for members and partners.", "وصف من سطر واحد للأعضاء والشركاء.") : t("Tell the owner what you will contribute and why this shared context matters.", "أخبر المالك بما ستساهم به ولماذا يهم هذا السياق المشترك.")} /></label><label>{mode === "new" ? t("Your organization role", "دورك في المنظمة") : t("Your requested role", "الدور الذي تطلبه")}<select value={role} onChange={(event) => setRole(event.target.value)}><option>{t("Founder / Owner", "مؤسس / مالك")}</option><option>{t("Team member", "عضو فريق")}</option><option>{t("Mentor", "مرشد")}</option><option>{t("Advisor", "مستشار")}</option></select></label><button className="button button-primary" type="submit" disabled={readiness < 3}>{sent ? t("Request sent", "تم إرسال الطلب") : mode === "new" ? t("Create workspace draft", "أنشئ مسودة مساحة عمل") : t("Send join request", "أرسل طلب الانضمام")} <ArrowRight size={14} /></button>{sent && <div className="inline-success" role="status"><Check size={15} /> {mode === "new" ? t("Workspace draft created. Your identity remains personal; invite teammates into clear organization roles next.", "تم إنشاء مسودة مساحة العمل. تبقى هويتك شخصية؛ ادعُ زملاء الفريق إلى أدوار منظمة واضحة بعد ذلك.") : t("The workspace owner will review your role and context before granting access.", "سيراجع مالك مساحة العمل دورك وسياقك قبل منح الوصول.")}</div>}</form></ProductShell>;
}

const DEMO_COUPON = "FOUNDER20";

export function EventFlow() {
  const { t, formatNum } = useLocale();
  const { isAuthed } = useAuth();
  const [location, setLocation] = useLocation();
  const params = useParams<{ slug: string }>();
  const event = events.find((item) => item.slug === params.slug) ?? events[0];
  const [registered, setRegistered] = useState(false);
  const [saved, setSaved] = useState(false);
  const [coupon, setCoupon] = useState("");
  const [couponApplied, setCouponApplied] = useState(false);
  const isDashboard = location.startsWith("/dashboard");
  const price = event.price;
  const discounted = price && couponApplied ? Math.round(price * 0.8) : price;

  const register = () => {
    if (!isAuthed) { setLocation(`/signup?intent=register&event=${event.slug}`); return; }
    setRegistered(true);
  };
  const saveForLater = () => {
    if (!isAuthed) { setLocation("/signup?intent=save-event"); return; }
    setSaved((value) => !value);
  };
  const applyCoupon = () => { if (coupon.trim().toUpperCase() === DEMO_COUPON) setCouponApplied(true); };

  const eventMonth = t(event.month, monthAr[event.month] ?? event.month);
  const content = <><div className="event-room-hero"><div><SignalTag>{t(event.tag, event.arTag)} / {formatNum(event.day)} {eventMonth}</SignalTag><h1>{t(event.title, event.arTitle)}</h1><p>{t(event.copy, event.arCopy)}</p></div><div className="event-room-date"><span className="mono">{t(event.location, event.arLocation)}</span><strong>{formatNum(event.day)}</strong><span>{eventMonth}</span></div></div><div className="event-room-grid"><main><SectionLabel>{t("Why this event", "لماذا هذه الفعالية")}</SectionLabel><h2>{t(`Come with one question. ${event.outcome}.`, `تعال بسؤال واحد. ${event.arOutcome}.`)}</h2><p className="reading-copy">{t("Built around practical operator sessions, not stage-only inspiration. Bring your real problem and use the agenda to find the people closest to it.", "مبنية حول جلسات مشغلين عملية، لا إلهاما من على المسرح فقط. أحضر مشكلتك الحقيقية واستخدم الأجندة لتجد الأشخاص الأقرب إليها.")}</p><div className="event-agenda"><div><span className="mono">{formatNum(event.meta.match(/\d{1,2}:\d{2}/)?.[0] ?? "18:30")}</span><strong>{t("Arrival and operator mixer", "الوصول ولقاء المشغلين")}</strong><p>{t("Small tables, one prompt, no pitches.", "طاولات صغيرة، محفز واحد، بلا عروض.")}</p></div><div><span className="mono">{formatNum("19:15")}</span><strong>{t("Working session", "جلسة عمل")}</strong><p>{t("What customers actually recognize as value.", "ما يعتبره العملاء قيمة فعلا.")}</p></div><div><span className="mono">{formatNum("20:15")}</span><strong>{t("Founder-to-founder sessions", "جلسات مؤسس لمؤسس")}</strong><p>{t("Bring your live decision to the table.", "أحضر قرارك الحالي إلى الطاولة.")}</p></div></div></main><aside className="registration-card"><SectionLabel>{t(`Seat / ${event.seats} available`, `مقعد / ${event.seats} متاح`)}</SectionLabel><h2>{registered ? t("You're registered.", "أنت مسجَل.") : t("Reserve your place.", "احجز مكانك.")}</h2><p>{registered ? t("The event is saved to your workspace. We'll remind you before doors open.", "حُفظت الفعالية في مساحة عملك. سنذكرك قبل بدئها.") : t("Choose a pass and we'll keep the event, agenda, and people close.", "اختر تذكرة وسنبقي الفعالية والأجندة والأشخاص قريبين.")}</p><div className="pass-option selected"><span><strong>{price ? t("Founder pass", "تذكرة المؤسس") : t("Free pass", "تذكرة مجانية")}</strong><small>{t(event.tag, event.arTag)}</small></span><b>{price ? (couponApplied ? <>${discounted} <s style={{ opacity: .5, fontSize: 12 }}>${price}</s></> : `$${price}`) : t("Free", "مجانا")}</b><Check size={15} /></div>{price != null && !registered && <div className="coupon-row"><input value={coupon} onChange={(event) => setCoupon(event.target.value)} placeholder={t("Coupon code", "كود الخصم")} aria-label={t("Coupon code", "كود الخصم")} disabled={couponApplied} /><button type="button" className="button button-ghost button-small" onClick={applyCoupon} disabled={couponApplied}>{couponApplied ? t("Applied", "تم التطبيق") : t("Apply", "طبق")}</button></div>}<button type="button" className="button button-primary full" onClick={() => registered ? setLocation("/dashboard/events") : register()}>{registered ? t("View in my events", "شاهد في فعالياتي") : price ? t("Buy ticket", "اشترِ التذكرة") : t("Register for event", "سجل في الفعالية")} <ArrowRight size={14} /></button><button type="button" className="button button-ghost full" aria-pressed={saved} onClick={saveForLater}><Save size={14} /> {saved ? t("Saved to shortlist", "أُضيف إلى القائمة") : t("Save for later", "احفظ لوقت لاحق")}</button>{saved && <span className="action-feedback" role="status"><Check size={13} /> {t("Saved to your workspace.", "حُفظ في مساحة عملك.")}</span>}{!isAuthed && <p className="form-hint">{t("Sign in to register, it also unlocks event recommendations tailored to what you're building.", "سجل الدخول للتسجيل، كما يفتح لك توصيات فعاليات مخصصة لما تبنيه.")}</p>}</aside></div></>;

  if (isDashboard) return <ProductShell title={t(event.title, event.arTitle)} active="/dashboard/events">{content}</ProductShell>;
  return <section className="section"><div className="container">{content}</div></section>;
}

